import{_ as a,o as r,c as o,a4 as e}from"./chunks/framework.9tZL7ZIQ.js";const c=JSON.parse('{"title":"美国运通（American Express）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/美国运通.md","filePath":"03_companies/美国运通.md"}'),d={name:"03_companies/美国运通.md"};function l(i,t,n,h,s,u){return r(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="美国运通-american-express" tabindex="-1">美国运通（American Express） <a class="header-anchor" href="#美国运通-american-express" aria-label="Permalink to &quot;美国运通（American Express）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>American Express Company (Amex)</td></tr><tr><td>行业</td><td>金融服务 / 支付</td></tr><tr><td>成立年份</td><td>1850年</td></tr><tr><td>总部</td><td>纽约州纽约市</td></tr><tr><td>伯克希尔持股</td><td>约 20%（长期持有，截至2021年为19.9%）</td></tr><tr><td>首次投资</td><td>1964年（色拉油丑闻后）</td></tr><tr><td>代表性投资</td><td>1991-1995年重新买入并长期持有</td></tr><tr><td>伯克希尔总成本</td><td>约13亿美元</td></tr><tr><td>最新市值占比</td><td>约占伯克希尔净资产的5%（截至2022年）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>美国运通是全球领先的金融服务公司，主要业务包括：</p><ul><li><strong>支付网络</strong>：运营全球性信用卡及支付网络，与 Visa、Mastercard 竞争</li><li><strong>信用卡业务</strong>：发行个人及企业信用卡，提供消费信贷</li><li><strong>商旅服务</strong>：商务旅行管理、旅游服务（公司传统优势领域）</li><li><strong>财富管理</strong>：资产管理、投资咨询等增值服务（原IDS部门，后分拆为Ameriprise）</li></ul><p>美国运通以&quot;只服务优质客户&quot;著称，持卡人多为高收入群体，拥有强大的品牌溢价能力和较高的卡片年费收入。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="第一次投资-1950年代-1960年代" tabindex="-1">第一次投资（1950年代-1960年代） <a class="header-anchor" href="#第一次投资-1950年代-1960年代" aria-label="Permalink to &quot;第一次投资（1950年代-1960年代）&quot;">​</a></h3><p>巴菲特与美国运通的渊源可以追溯到<strong>1953年</strong>，当时他就首次购买了美国运通IDS（投资部门）的股票，因为其市盈率仅为3倍，巴菲特甚至写了一份长篇报告，通过《华尔街日报》广告以1美元价格出售。</p><p><strong>1963-1964年</strong>，美国运通爆发了著名的<strong>色拉油丑闻</strong>（Salad Oil Scandal）：公司被发现其仓储的色拉油存货存在巨额欺诈，面临远超资本金的或有负债，股价从约60美元暴跌至约30美元，市场认为公司可能破产。</p><p>巴菲特在仔细研究后得出判断：<strong>丑闻损害的是公司的资产负债表，但没有损害美国运通这个名字的特许权价值</strong>。美国运通的核心业务——旅行支票和信用卡——所依赖的品牌信誉并未受到根本损害。</p><p>最终，巴菲特将当时<strong>巴菲特合伙有限公司约40%的资本（约1300万美元）投入美国运通</strong>，这是合伙企业有史以来最大的一笔投资，获得了美国运通超过5%的所有权。这笔投资最终获利约200%，成为巴菲特早期经典投资案例。</p><p>在1980年股东信中，巴菲特将这个案例总结为：</p><blockquote><p>GEICO当时的问题，就像1964年色拉油丑闻后的美国运通。都是独一无二的公司，暂时被财政打击晃了一下，但根本没有摧毁它们非凡的底层经济。 extraordinary 商业特许经营权，只是局部得了可切除的癌症（当然，需要技术熟练的外科医生），要区别于真正的&quot;扭转&quot;情况——那种情况管理层期待——也需要——让企业脱胎换骨。</p></blockquote><h3 id="重新投资-1991年至今" tabindex="-1">重新投资（1991年至今） <a class="header-anchor" href="#重新投资-1991年至今" aria-label="Permalink to &quot;重新投资（1991年至今）&quot;">​</a></h3><p>1991年，伯克希尔通过私募购买了<strong>3亿美元的美国运通PERCS</strong>（一种带上限收益的普通股衍生证券）。这是巴菲特第二次大规模投资美国运通。</p><p>PERCS原定1994年8月转换为普通股。转换前一个月，巴菲特正在考虑是否出售：美国运通面临维萨等发卡机构的激烈竞争，其未来潜力存在疑问。这时一个偶然事件改变了决策：巴菲特在高尔夫球场上遇到赫兹CEO弗兰克·奥尔森，当询问他对卡业务的看法时，弗兰克在两个洞之间就说服了巴菲特：<strong>美国运通的公司卡是一个了不起的特许经营权</strong>。巴菲特当即决定不卖，转而继续加仓。</p><p>到1994年，伯克希尔已经累计投入<strong>13.6亿美元</strong>，持有美国运通不到10%的股份。对比两个时点的数据可以看到美国运通的成长：</p><ul><li>1964年：美国运通净利润<strong>1250万美元</strong>，伯克希尔投入<strong>1300万美元</strong>获得5%股权</li><li>1994年：美国运通净利润<strong>14亿美元</strong>，伯克希尔投入<strong>13.6亿美元</strong>获得10%不到股权</li></ul><p>1995年，巴菲特进一步将持股增加到约<strong>10%</strong>。到1997年，这笔投资已经带来<strong>30亿美元</strong>的账面收益。</p><p>自1998年最后一次增持后，伯克希尔再也没有卖出过美国运通股票，一直持有至今。截至2023年，这种&quot;长睡不起&quot;的持有已经持续了<strong>超过25年</strong>。</p><h3 id="持股变化时间线" tabindex="-1">持股变化时间线 <a class="header-anchor" href="#持股变化时间线" aria-label="Permalink to &quot;持股变化时间线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>持股比例</th><th>事件</th></tr></thead><tbody><tr><td>1964</td><td>5%+</td><td>色拉油丑闻后抄底，投入合伙公司40%资本</td></tr><tr><td>1960年代末</td><td>-</td><td>获利了结，全部卖出</td></tr><tr><td>1991</td><td>-</td><td>买入3亿美元PERCS私募，重新开启投资</td></tr><tr><td>1994</td><td>&lt;10%</td><td>转换后增持，累计成本13.6亿美元</td></tr><tr><td>1995</td><td>~10%</td><td>继续增持，基本完成建仓</td></tr><tr><td>1998</td><td>11.3%</td><td>最后一次小幅增持</td></tr><tr><td>2011</td><td>13.0%</td><td>公司回购提升持股比例</td></tr><tr><td>2014</td><td>14.8%</td><td>公司回购提升持股比例</td></tr><tr><td>2018</td><td>17.9%</td><td>公司回购提升持股比例</td></tr><tr><td>2021</td><td>19.9%</td><td>公司回购提升持股比例</td></tr><tr><td>至今</td><td>~20%</td><td>持续持有，无变动</td></tr></tbody></table><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-强大的品牌与声誉" tabindex="-1">1. 强大的品牌与声誉 <a class="header-anchor" href="#_1-强大的品牌与声誉" aria-label="Permalink to &quot;1. 强大的品牌与声誉&quot;">​</a></h3><ul><li>&quot;运通卡&quot;在全球范围内享有极高认知度，超过170年历史沉淀</li><li>高端品牌形象深入人心，成为身份象征</li><li>持卡人品牌忠诚度极高，客户留存率远超行业平均</li></ul><h3 id="_2-高价值客户群体" tabindex="-1">2. 高价值客户群体 <a class="header-anchor" href="#_2-高价值客户群体" aria-label="Permalink to &quot;2. 高价值客户群体&quot;">​</a></h3><ul><li>聚焦服务于高收入、高消费群体</li><li>商旅人士首选支付工具</li><li>客户生命周期价值（LTV）远高于行业平均</li></ul><h3 id="_3-网络效应与闭环模式" tabindex="-1">3. 网络效应与闭环模式 <a class="header-anchor" href="#_3-网络效应与闭环模式" aria-label="Permalink to &quot;3. 网络效应与闭环模式&quot;">​</a></h3><ul><li>受理商户网络覆盖全球</li><li>发卡量与商户网络相互强化</li><li>闭环支付系统带来更高利润率和客户数据</li></ul><h3 id="_4-持久的品牌护城河" tabindex="-1">4. 持久的品牌护城河 <a class="header-anchor" href="#_4-持久的品牌护城河" aria-label="Permalink to &quot;4. 持久的品牌护城河&quot;">​</a></h3><p>真正伟大的企业必须有持久的&quot;护城河&quot;，保护投入资本获得高额回报。资本主义动力学保证，竞争对手会不断攻击任何赚取高回报的企业&quot;城堡&quot;。因此，<strong>强大的壁垒，比如成为低成本生产商，或者拥有全球强大品牌（可口可乐，吉列，美国运通），对持续成功至关重要。</strong> —— 2007年股东信</p><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;美国运通做的事情与可口可乐和吉列没什么不同——它们都在销售&#39;品牌&#39;。&quot;</p></blockquote><blockquote><p>&quot;GEICO当时的问题，就像1964年色拉油丑闻后的美国运通。都是独一无二的公司，暂时被财政打击晃了一下，但根本没有摧毁它们非凡的底层经济。 extraordinary 商业特许经营权，只是局部得了可切除的癌症。&quot; —— 1980年</p></blockquote><blockquote><p>&quot;我的美国运通历史包括几段插曲：在1960年代中期，就在股票因公司臭名昭著的色拉油丑闻而暴跌之后，我们将巴菲特合伙有限公司约40%的资本投入该股票——这是合伙企业有史以来最大的投资。&quot; —— 1994年</p></blockquote><blockquote><p>&quot;这就是我运气的地方。在那个决策月份，我在缅因州普劳茨 Neck 与赫兹首席执行官弗兰克·奥尔森一起打高尔夫。弗兰克是一位出色的管理者，对卡业务有深入了解。所以从第一个发球台开始我就向他询问该行业的情况。当我们到达第二个果岭时，弗兰克已说服我美国运通的公司卡是一个了不起的特许经营权，我决定不出售。在后九洞我转为买家，几个月内伯克希尔拥有公司10%的股份。我们现在在美国运通股份上有30亿美元的收益，我自然对弗兰克感到非常感激。&quot; —— 1997年</p></blockquote><blockquote><p>&quot;公平地说，我们也看到了很多成功案例，有些确实非常出色。有许多大公司的管理者让我非常钦佩；美国运通的肯·切诺尔特（Ken Chenault）、通用电气的杰夫·伊梅尔特和富国银行的迪克·科瓦切维奇很快就浮现在脑海中。&quot; —— 2006年</p></blockquote><blockquote><p>&quot;真正伟大的企业必须有持久的&#39;护城河&#39;，保护投入资本获得高额回报。因此，强大的壁垒，比如成为低成本生产商，或者拥有全球强大品牌（可口可乐，吉列，美国运通），对持续成功至关重要。&quot; —— 2007年</p></blockquote><blockquote><p>&quot;有趣的是，美国运通和富国银行都是Henry Wells和William Fargo组织成立的，运通1850年，富国1852年。宝洁和可口可乐分别1837年和1886年开始做生意。初创企业不是我们的游戏。&quot; —— 2007年</p></blockquote><blockquote><p>&quot;以上表中的一个例子为例：伯克希尔持有的美国运通股份在过去八年中保持不变。与此同时，由于公司的回购，我们的持股比例从12.6%上升到17.9%。去年，伯克希尔在美国运通69亿美元收益中的份额是12亿美元，约占我们为该公司股份支付的13亿美元的96%。当收益增加而流通股减少时，所有者——随着时间的推移——通常会做得很好。&quot; —— 2018年</p></blockquote><blockquote><p>&quot;美国运通于1850年开始运营……多年来，两家公司都尝试向不相关领域扩张，但都发现这些尝试收效甚微。在过去——但绝对不是现在——两家公司甚至都被管理不善。但每家在其核心业务上都取得了巨大成功，并随着条件的变化不时重塑。至关重要的是，他们的产品&#39;走向世界&#39;。可口可乐和美国运通都成为了全球认可的品牌名称，就像他们的核心产品一样，液体消费和无争议的金融信任是我们世界永恒的必需品。&quot; —— 2023年</p></blockquote><blockquote><p>&quot;2023年，我们没有买卖美国运通或可口可乐的任何股票——延续了我们自己的&#39;长睡者&#39;——这种沉睡已经持续了二十多年。去年，两家公司都通过增加收益和股息来奖励我们的不作为。事实上，我们2023年获得的美国运通收益份额大大超过了我们很久以前购买时花费的13亿美元。&quot; —— 2023年</p></blockquote><blockquote><p>&quot;可口可乐和美国运通的经验教训？当你发现一家真正出色的企业时，坚持持有它。耐心是有回报的，一家有出色的企业可以抵消许多不可避免的平庸决策。&quot; —— 2023年</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><h3 id="伯克希尔投资回报" tabindex="-1">伯克希尔投资回报 <a class="header-anchor" href="#伯克希尔投资回报" aria-label="Permalink to &quot;伯克希尔投资回报&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数据</th></tr></thead><tbody><tr><td>总成本</td><td>约13亿美元（1995年完成收购）</td></tr><tr><td>1995年股息收入</td><td>4100万美元</td></tr><tr><td>2022年股息收入</td><td>3.02亿美元</td></tr><tr><td>2022年底市值</td><td>220亿美元</td></tr><tr><td>账面收益（2022年底）</td><td>~207亿美元</td></tr><tr><td>累计回报率（不含股息再投资）</td><td>~1600%</td></tr></tbody></table><h3 id="美国运通自身成长" tabindex="-1">美国运通自身成长 <a class="header-anchor" href="#美国运通自身成长" aria-label="Permalink to &quot;美国运通自身成长&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>净利润</th><th>伯克希尔持股比例</th><th>伯克希尔享有的净利润</th></tr></thead><tbody><tr><td>1964</td><td>1250万美元</td><td>5%</td><td>62.5万美元</td></tr><tr><td>1994</td><td>14亿美元</td><td>&lt;10%</td><td>&lt;1.4亿美元</td></tr><tr><td>2018</td><td>69亿美元</td><td>17.9%</td><td>12亿美元</td></tr><tr><td>2023</td><td>-</td><td>~20%</td><td>&gt; 13亿美元+</td></tr></tbody></table><h3 id="股息增长" tabindex="-1">股息增长 <a class="header-anchor" href="#股息增长" aria-label="Permalink to &quot;股息增长&quot;">​</a></h3><ul><li>1995年：4100万美元</li><li>2022年：3.02亿美元</li><li><strong>增长幅度</strong>：639%</li><li><strong>年均增长率</strong>：约7.5%</li></ul><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><strong>哈维·戈卢布（Harvey Golub）</strong> - 1990年代CEO，带领美国运通复兴，巴菲特评价其&quot;非常出色&quot;最大化了公司潜力</li><li><strong>肯·切诺尔特（Ken Chenault）</strong> - 2001-2018年CEO，巴菲特公开钦佩的杰出管理者</li><li><strong>弗兰克·奥尔森（Frank Olson）</strong> - 赫兹CEO，1994年高尔夫球场上一席话说服巴菲特继续持有</li><li><strong>亨利·威尔斯（Henry Wells）</strong> &amp; <strong>威廉·法戈（William Fargo）</strong> - 美国运通联合创始人，后来又创立了<a href="/03_companies/富国银行">富国银行</a></li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1967, 1980, 1991, 1992, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2005, 2006, 2007, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="/03_companies/可口可乐">可口可乐</a> - 同期重要持仓，同为品牌护城河典范</li><li><a href="/03_companies/富国银行">富国银行</a> - 同为威尔斯法戈创立，长期四大持仓之一</li><li><a href="/03_companies/吉列">吉列</a> - 同为品牌护城河代表企业</li><li><a href="/03_companies/GEICO">GEICO</a> - 同为&quot;可切除局部癌症&quot;投资案例</li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1980年/翻译">/01_letters/1980年/翻译</a></li><li><a href="/01_letters/1991年/翻译">/01_letters/1991年/翻译</a></li><li><a href="/01_letters/2023年/翻译">/01_letters/2023年/翻译</a></li><li><a href="/01_letters/2024年/翻译">/01_letters/2024年/翻译</a></li></ul>',63)])])}const b=a(d,[["render",l]]);export{c as __pageData,b as default};
